import { useCallback, useRef, useState } from 'react'
import type { StyleDesc } from '@gpuix/react'
import { Toast, type ToastType } from './Toast'

/** One toast row. `id` is generated by `useToasts()`; it is optional on the
 *  input type for backward compatibility with plain `{message, actionLabel,
 *  onAction}` arrays. */
export interface ToastItem {
  message: string
  id?: string
  type?: ToastType
  /** Auto-expiry in ms (default 5000; `0` = sticky). */
  duration?: number
  actionLabel?: string
  onAction?: () => void
}

/** Options for `useToasts().toast(message, opts)`. */
export interface ToastOptions {
  type?: ToastType
  /** Auto-expiry in ms (default 5000; `0` = sticky). */
  duration?: number
  actionLabel?: string
  onAction?: () => void
}

/**
 * The imperative front-end for the data-driven `Toaster` (GPUix has no global
 * event bus — a hook is the idiom). Returns:
 *
 * - `toasts` — the current `ToastItem[]` (pass to `<Toaster toasts={toasts} />`),
 * - `toast(message, opts?)` — push a toast (id generated via a useRef counter;
 *   `setTimeout`-driven expiry, default 5000ms, per-toast `duration` override;
 *   returns the generated id),
 * - `dismiss(id)` — remove a toast by id (also wired to the pill's close button
 *   via `<Toaster onDismiss={dismiss} />`).
 */
export function useToasts() {
  const [toasts, setToasts] = useState<ToastItem[]>([])
  const counter = useRef(0)

  const dismiss = useCallback((id: string) => {
    setToasts((current) => current.filter((toast) => toast.id !== id))
  }, [])

  const toast = useCallback(
    (message: string, opts: ToastOptions = {}) => {
      counter.current += 1
      const id = `toast-${counter.current}`
      setToasts((current) => [...current, { id, message, ...opts }])
      const duration = opts.duration ?? 5000
      if (duration > 0) setTimeout(() => dismiss(id), duration)
      return id
    },
    [dismiss],
  )

  return { toasts, toast, dismiss }
}

export type ToasterPosition = 'bottom-left' | 'bottom-right' | 'top-right' | 'top-left'

const POSITION_OFFSETS: Record<ToasterPosition, Partial<StyleDesc>> = {
  'bottom-left': { bottom: 16, left: 16 },
  'bottom-right': { bottom: 16, right: 16 },
  'top-right': { top: 16, right: 16 },
  'top-left': { top: 16, left: 16 },
}

export interface ToasterProps {
  toasts?: ToastItem[]
  /** Corner of the positioned parent (16px insets). Default `bottom-left`. */
  position?: ToasterPosition
  /** Called with the toast id when a pill's close button is pressed. */
  onDismiss?: (id: string) => void
  style?: Partial<StyleDesc>
}

/**
 * A Sonner-like toast container: a corner stack of `Toast` pills, positioned
 * over its (positioned) parent. Reuses the existing `Toast`; pair with
 * `useToasts()` for the imperative `toast()` / `dismiss(id)` front-end.
 */
export function Toaster({ toasts = [], position = 'bottom-left', onDismiss, style }: ToasterProps) {
  return (
    <div
      style={{
        position: 'absolute',
        ...POSITION_OFFSETS[position],
        display: 'flex',
        flexDirection: 'column',
        gap: 8,
        ...style,
      }}
    >
      {toasts.map((toast, i) => {
        const id = toast.id
        return (
          <Toast
            key={id ?? i}
            message={toast.message}
            type={toast.type}
            actionLabel={toast.actionLabel}
            onAction={toast.onAction}
            onDismiss={onDismiss ? () => onDismiss(id ?? '') : undefined}
          />
        )
      })}
    </div>
  )
}
